function collides(x,y){const blockers=[[14*T,10*T,47],[20*T,7*T,48],[25*T,11*T,46],[4*T,9*T,27],[5*T,11*T,24],[9*T,9*T,24],[10*T,7*T,26],[12*T,7*T,24],[16*T,5*T,28],[22*T,4*T,29],[24*T,5*T,25],[28*T,8*T,29],[29*T,10*T,25],[16*T,15*T,24],[20*T,13*T,27],[23*T,15*T,25],[10*T,17*T,29],[5*T,18*T,28],[28*T,17*T,29],[2*T,5*T,28]];return blockers.some(([a,b,r])=>Math.hypot(x-a,y-b)<r)}let prev=0;function loop(ts){move(Math.min(32,ts-prev));prev=ts;requestAnimationFrame(loop)}requestAnimationFrame(loop);
